export function assignMembershipWeights<T>(
    items: readonly KeyedValue<T>[],
    activeKeys: readonly string[],
    activeWeight = 1,
    inactiveWeight = 0.25
): WeightedValue<T>[] {
    validateWeight(activeWeight);
    validateWeight(inactiveWeight);

    const active = new Set<string>();
    for (const key of activeKeys) {
        validateKey(key);
        active.add(key);
