import { assignMembershipWeights, KeyedValue } from "./solution";

function assert(condition: boolean, message: string): void {
    if (!condition) throw new Error(message);
}

function throws(action: () => unknown, expected: typeof TypeError | typeof RangeError, message: string): void {
    let error: unknown;
    try { action(); } catch (caught) { error = caught; }
    assert(error instanceof expected, message);
}

const shared = { marker: "shared" };
const first: KeyedValue<typeof shared> = { key: "A", value: shared };
const second: KeyedValue<typeof shared> = { key: "b", value: shared };
const duplicate: KeyedValue<typeof shared> = { key: "A", value: shared };
const items = Object.freeze([Object.freeze(first), Object.freeze(second), Object.freeze(duplicate)]);
const active = Object.freeze(["A", "A", "a"]);
const result = assignMembershipWeights(items, active);

assert(result.length === 3, "preserves item count");
assert(result[0].key === "A" && result[0].weight === 1, "active item gets default active weight");
assert(result[1].key === "b" && result[1].weight === 0.25, "inactive item gets default inactive weight");
assert(result[2].key === "A" && result[2].weight === 1, "duplicate item keys are weighted independently");
assert(result[0].value === shared && result[1].value === shared, "value references are preserved");
assert(result[0] !== first && result[1] !== second, "new wrapper objects are returned");
assert(result[0].key === "A" && result[1].key === "b" && result[2].key === "A", "item order is preserved");

result[0].key = "changed";
result[0].weight = 0;
assert(first.key === "A" && assignMembershipWeights(items, active)[0].weight === 1, "output mutation does not affect inputs or later calls");

const custom = assignMembershipWeights(items, ["b"], 0, 1);
assert(custom[0].weight === 1 && custom[1].weight === 0 && custom[2].weight === 1, "inclusive boundary weights are accepted");
assert(assignMembershipWeights([], []).length === 0, "empty inputs are accepted");
assert(assignMembershipWeights([], []) !== assignMembershipWeights([], []), "empty result arrays are fresh");

for (const invalidWeight of [NaN, Infinity, -Infinity, -0.01, 1.01]) {
    throws(() => assignMembershipWeights([], [], invalidWeight), RangeError, "invalid active weight throws RangeError");
    throws(() => assignMembershipWeights([], [], 1, invalidWeight), RangeError, "invalid inactive weight throws RangeError");
}
throws(() => assignMembershipWeights([], [], "1" as unknown as number), RangeError, "non-number weight throws RangeError");

for (const invalidKey of ["", " ", "\n\t"]) {
    throws(() => assignMembershipWeights([{ key: invalidKey, value: 1 }], []), TypeError, "invalid item key throws TypeError");
    throws(() => assignMembershipWeights([], [invalidKey]), TypeError, "invalid active key throws TypeError");
}
throws(() => assignMembershipWeights([{ key: 4 as unknown as string, value: 1 }], []), TypeError, "non-string item key throws TypeError");
throws(() => assignMembershipWeights([], [null as unknown as string]), TypeError, "non-string active key throws TypeError");

const outsideRangeInvalid: readonly KeyedValue<number>[] = [{ key: "valid", value: 1 }, { key: " ", value: 2 }];
throws(() => assignMembershipWeights(outsideRangeInvalid, []), TypeError, "every item key is validated");

